<template>
  <div>
    <!-- <v-card>
      <div class="ml-4 pt-2 header-text-style font-weight-bold">연결된 밴드 목록</div>
      <v-card-text>
        <v-chip
          v-for="band in bands"
          :key="band.id"
          class="ma-1"
          color="secondary"
          background-color="white"
          outlined
          @click="moveToMarker(band)"
        >
          {{ band.name }}
        </v-chip>
      </v-card-text></v-card
    ><v-divider class="mt-4" /> -->
    <v-card>
      <div class="ml-4 pt-2 header-text-style font-weight-bold">연결된 밴드 위치</div>
      <div style="width: 100%; height: 45vh" id="kakaoMap" />
      <div class="pa-2 text-caption text-right grey--text">
        마지막 업데이트: {{ lastUpdateTime || '업데이트 정보 없음' }}
      </div>
    </v-card>
  </div>
</template>

<script>
export default {
  name: 'DashboardMap',
  props: {},

  data() {
    return {
      gpsData: null,
      map: null,
      markers: [],
      overlays: [],
      infowindows: [],
      bands: [],
      // 초기 중심좌표 (서울시청)
      center: {
        lat: 37.566826,
        lng: 126.978656,
      },
      lastUpdateTime: new Date().toLocaleString(),
    }
  },

  async mounted() {
    // 1. 연결된 위치 정보 가져오기
    await this.fetchConnectedLocations()
    // 2. 카카오맵 스크립트 로드
    this.loadKakaoMapScript()
  },

  created() {
    this.$session.$on('gps', this.handleGPSData)
  },

  beforeDestroy() {
    this.$session.$off('gps', this.handleGPSData)
    if (this.infowindow) {
      this.infowindow.close()
    }
    if (this.marker) {
      this.marker.setMap(null)
    }
    this.map = null
  },

  methods: {
    /**
     * GPS 데이터를 처리하는 함수
     * @param {Object} data - GPS 데이터 객체
     * @param {string} data.bid - 밴드 ID
     * @param {number} data.latitude - 위도
     * @param {number} data.longitude - 경도
     *
     * 기능:
     * 1. 세션 사용자 확인
     * 2. 받은 GPS 데이터로 해당 밴드 찾기
     * 3. 밴드의 위치 정보 업데이트
     * 4. 기존 마커/오버레이/인포윈도우 제거
     * 5. 새로운 위치에 마커, 커스텀 오버레이, 인포윈도우 생성
     * 6. 마커에 마우스 이벤트 리스너 추가
     * 7. 지도 중심 이동 및 최종 업데이트 시간 갱신
     */
    handleGPSData(data) {
      if (!this.$session.user) {
        return
      }
      this.gpsData = data

      // 해당 bid를 가진 밴드 찾기
      const targetBand = this.bands.find((band) => band.bid === data.bid)
      if (!targetBand) {
        return
      }

      // 찾은 밴드의 위치 정보 업데이트
      targetBand.latitude = data.latitude
      targetBand.longitude = data.longitude

      const bandIndex = this.bands.findIndex((band) => band.id === data.bid)
      if (bandIndex !== -1) {
        // 기존 마커와 오버레이 제거
        if (this.markers[bandIndex]) {
          this.markers[bandIndex].setMap(null)
        }
        if (this.infowindows[bandIndex]) {
          this.infowindows[bandIndex].close()
        }
        if (this.overlays[bandIndex]) {
          this.overlays[bandIndex].setMap(null)
        }

        // 새로운 위치에 마커 생성
        const position = new window.kakao.maps.LatLng(data.latitude, data.longitude)
        const marker = new window.kakao.maps.Marker({
          map: this.map,
          position: position,
        })

        // 새로운 인포윈도우 생성
        const infowindow = new window.kakao.maps.InfoWindow({
          content: `<div style="padding:5px;font-size:12px;">
          <strong>${targetBand.name}</strong><br>
          <span>위도: ${data.latitude.toFixed(6)}</span><br>
          <span>경도: ${data.longitude.toFixed(6)}</span><br>
          <span style="color: #888;">최근 업데이트: ${new Date().toLocaleTimeString()}</span>
        </div>`,
        })

        // 새로운 오버레이 생성
        const customOverlay = new window.kakao.maps.CustomOverlay({
          map: this.map,
          position: position,
          content: `
        <div style="
          padding: 5px;
          background: rgba(255, 255, 255, 0.9);
          border-radius: 4px;
          border: 1px solid #ccc;
          font-size: 12px;
          font-weight: bold;
          position: relative;
          bottom: 40px;
          text-align: center;
          min-width: 60px;
          z-index: 9999;
        ">
          ${targetBand.name}
        </div>`,
          yAnchor: 1,
          zIndex: 9999,
        })

        // 마커와 인포윈도우 배열 업데이트
        this.markers[bandIndex] = marker
        this.infowindows[bandIndex] = infowindow
        this.overlays[bandIndex] = customOverlay

        // 마커 이벤트 리스너 추가
        window.kakao.maps.event.addListener(marker, 'mouseover', () => {
          infowindow.open(this.map, marker)
        })

        window.kakao.maps.event.addListener(marker, 'mouseout', () => {
          infowindow.close()
        })
        this.map.panTo(position)
      }

      // GPS 데이터를 받을 때마다 시간 업데이트
      this.lastUpdateTime = new Date().toLocaleString()
    },
    /**
     * 카카오맵 API 스크립트를 동적으로 로드하는 함수
     *
     * 기능:
     * 1. 카카오맵 API가 이미 로드되어 있는지 확인
     * 2. 이미 로드된 경우 바로 지도 초기화
     * 3. 로드되지 않은 경우:
     *    - 스크립트 태그 생성
     *    - API 키를 포함한 카카오맵 SDK URL 설정
     *    - 비동기 로드 설정
     *    - 스크립트 로드 완료 시 지도 초기화
     *    - HTML head에 스크립트 추가
     *
     * @returns {void}
     */
    loadKakaoMapScript() {
      if (window.kakao && window.kakao.maps) {
        this.initMap()
        return
      }

      const script = document.createElement('script')

      script.src = `//dapi.kakao.com/v2/maps/sdk.js?appkey=${process.env.VUE_APP_KAKAO_MAPS_API_KEY}&autoload=false`
      script.async = true

      script.onload = () => {
        window.kakao.maps.load(() => {
          this.initMap()
        })
      }

      document.head.appendChild(script)
    },

    /**
     * 카카오맵을 초기화하고 기본 설정을 적용하는 함수
     *
     * 기능:
     * 1. 지도 컨테이너 요소 선택
     * 2. 기본 지도 옵션 설정
     *    - 초기 중심 좌표 설정
     *    - 줌 레벨 설정 (level: 6)
     * 3. 지도 인스턴스 생성
     * 4. 지도 컨트롤 추가
     *    - 줌 컨트롤 (우측)
     *    - 지도 타입 컨트롤 (우측 상단)
     * 5. 마커 표시 함수 호출
     *
     * @returns {void}
     */
    initMap() {
      const mapContainer = document.getElementById('kakaoMap')
      const mapOptions = {
        center: new window.kakao.maps.LatLng(this.center.lat, this.center.lng),
        level: 6,
      }

      this.map = new window.kakao.maps.Map(mapContainer, mapOptions)

      // 지도 컨트롤 추가
      const zoomControl = new window.kakao.maps.ZoomControl()
      const mapTypeControl = new window.kakao.maps.MapTypeControl()

      this.map.addControl(zoomControl, window.kakao.maps.ControlPosition.RIGHT)
      this.map.addControl(mapTypeControl, window.kakao.maps.ControlPosition.TOPRIGHT)

      this.displayMarkers()
    },

    /**
     * 지도에 모든 밴드의 위치를 마커로 표시하는 함수
     *
     * 기능:
     * 1. 기존에 표시된 모든 마커, 인포윈도우, 오버레이 제거
     * 2. 각 밴드에 대해 다음 작업 수행:
     *    - 위치 좌표가 있는 경우에만 마커 생성
     *    - 밴드 이름이 표시되는 커스텀 오버레이 생성
     *    - 상세 정보가 표시되는 인포윈도우 생성
     * 3. 마커 이벤트 설정
     *    - mouseover: 인포윈도우 표시
     *    - mouseout: 인포윈도우 숨김
     * 4. 마지막 마커 위치로 지도 중심 이동
     *
     * @returns {void}
     */
    displayMarkers() {
      // 기존 마커들과 오버레이 제거
      this.markers.forEach((marker) => marker.setMap(null))
      this.infowindows.forEach((infowindow) => infowindow.close())
      this.overlays.forEach((overlay) => overlay.setMap(null))
      this.markers = []
      this.infowindows = []
      this.overlays = []

      this.bands.forEach((band) => {
        if (band.latitude && band.longitude) {
          const position = new window.kakao.maps.LatLng(band.latitude, band.longitude)

          const marker = new window.kakao.maps.Marker({
            map: this.map,
            position: position,
          })
          // 커스텀 오버레이 콘텐츠
          const content = `
        <div style="
          padding: 5px;
          background: rgba(255, 255, 255, 0.9);
          border-radius: 4px;
          border: 1px solid #ccc;
          font-size: 12px;
          font-weight: bold;
          position: relative;
          bottom: 40px;
          text-align: center;
          min-width: 60px;
          z-index: 9999;
        ">
          ${band.name}
        </div>`

          // 커스텀 오버레이 생성
          const customOverlay = new window.kakao.maps.CustomOverlay({
            map: this.map,
            position: position,
            content: content,
            yAnchor: 1,
            zIndex: 9999,
          })

          const infowindow = new window.kakao.maps.InfoWindow({
            content: `<div style="padding:5px;font-size:12px;">
            <strong>${band.name}</strong><br>
            <span>위도: ${band.latitude.toFixed(6)}</span><br>
            <span>경도: ${band.longitude.toFixed(6)}</span><br>
            <span style="color: #888;">최근 업데이트: ${new Date().toLocaleTimeString()}</span>
          </div>`,
          })

          this.markers.push(marker)
          this.infowindows.push(infowindow)
          this.overlays.push(customOverlay)

          window.kakao.maps.event.addListener(marker, 'mouseover', () => {
            infowindow.open(this.map, marker)
          })

          window.kakao.maps.event.addListener(marker, 'mouseout', () => {
            infowindow.close()
          })

          this.map.setCenter(position)
        }
      })
    },

    /**
     * 연결된 밴드들의 위치 정보를 서버로부터 가져오는 비동기 함수
     *
     * 기능:
     * 1. REST API를 통해 연결된 밴드들의 위치 정보 요청
     * 2. 성공 시 bands 배열에 위치 정보 저장
     * 3. 실패 시 콘솔에 에러 메시지 출력
     *
     * @throws {Error} API 호출 실패 시 에러
     * @returns {Promise<void>}
     */
    async fetchConnectedLocations() {
      try {
        const response = await this.$rest.connected_locations()

        this.bands = response
      } catch (error) {
        console.error('밴드 위치 정보를 불러오는데 실패했습니다:', error)
      }
    },
    /**
     * 특정 밴드의 마커로 지도 중심을 이동시키는 함수
     *
     * @param {Object} band - 이동할 대상 밴드 객체
     * @param {number} band.latitude - 밴드의 위도
     * @param {number} band.longitude - 밴드의 경도
     * @param {string} band.id - 밴드의 고유 ID
     *
     * 기능:
     * 1. 밴드의 위치 좌표 확인
     * 2. 해당 위치로 지도 중심 이동
     * 3. 줌 레벨 3으로 설정 (상세 뷰)
     * 4. 해당 마커의 인포윈도우 표시
     * 5. 3초 후 인포윈도우 자동 닫힘
     *
     * @returns {void}
     */
    moveToMarker(band) {
      if (band.latitude && band.longitude) {
        const position = new window.kakao.maps.LatLng(band.latitude, band.longitude)
        this.map.setCenter(position)
        this.map.setLevel(3) // 줌 레벨 설정 (낮을수록 더 가까이 보임)

        // 해당 마커의 인포윈도우 표시
        const markerIndex = this.bands.findIndex((b) => b.id === band.id)
        if (markerIndex !== -1) {
          this.infowindows[markerIndex].open(this.map, this.markers[markerIndex])

          // 3초 후 인포윈도우 자동으로 닫기
          setTimeout(() => {
            this.infowindows[markerIndex].close()
          }, 3000)
        }
      }
    },
  },

  watch: {
    bands: {
      handler() {
        if (this.map) {
          this.displayMarkers()
        }
      },
      deep: true,
    },
  },
}
</script>
